/**
 * Ügyenkénti forrás-ellenőrzés (2026-09-29-től).
 *
 * A user kérése: minden ügy címét, személyét, intézményét, összegét és
 * leírását össze kell vetni a forráscikkekkel, és ami nem stimmel, javítani
 * vagy törölni kell („ezekért beperelhetnek"). Az ellenőrzés előtt a
 * részletoldali leírásokat egy LLM generálta, és rendszeresen tartalmaztak a
 * forrásban nem szereplő, valakire terhelő állítást (pl. nem létező ítélet,
 * más ügyből átemelt vád).
 *
 * Minden ellenőrzött ügy ide kerül. A bejegyzés mezői felülírják a
 * CASE_OVERRIDES azonos mezőit (getCaseOverride() összefésüli), a
 * `descriptionBlocks` pedig a generált leírás helyébe lép. A DB-mezők
 * (cím, személy, intézmény, összefoglaló) javítása közvetlenül az
 * adatbázisban történik — itt csak a nyoma marad a `note`-ban.
 *
 * Az ajánlóba („Ezeket az ügyeket is érdemes elolvasni") csak az itt
 * `ok`/`fixed` minősítésű ügy kerülhet.
 */
import type { DescriptionBlock } from './ugyek-config';

export type AuditVerdict = 'ok' | 'fixed' | 'removed';

export interface CaseAuditEntry {
  checked: string;
  verdict: AuditVerdict;
  /** Mit találtunk és mit javítottunk — a következő ellenőrzőnek. */
  note: string;
  title?: string;
  summary?: string;
  hideAutoDamage?: boolean;
  damageText?: string;
  descriptionBlocks?: DescriptionBlock[];
  /**
   * Bűncselekmény-címkék az ügyoldalon. Ellenőrzött ügynél a generált
   * (DB offenceTypes) címkék NEM jelennek meg — csak ami itt szerepel, és
   * csak akkor, ha a forrás szerint az adott bűncselekmény miatt tényleges
   * eljárás, gyanúsítás, vád vagy ítélet van.
   */
  crimeTypes?: string[];
}

const card = (source: string, date: string, headline: string, url: string): DescriptionBlock => ({
  type: 'article-card',
  source,
  date,
  headline,
  url,
});
const text = (content: string): DescriptionBlock => ({ type: 'text', content });

