export function getCaseAudit(id: string): CaseAuditEntry | null {
  return CASE_AUDIT[id] ?? null;
}

/** Az ajánlóba csak kézzel ellenőrzött, nem törölt ügy kerülhet. */
export function isAuditApproved(id: string): boolean {
  const a = CASE_AUDIT[id];
  return !!a && a.verdict !== 'removed';
}
